insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('flag-players','flag','nfl-flag5-guide-review-required','foundation',array['under13','13-17','18plus'],'In the NFL FLAG 5-on-5 format described in the linked guide, how many players are on the field for each team?','["5","7","8","11"]'::jsonb,0,'The selected guide describes 5-on-5. Other flag formats have different player counts.','https://nflflag.com/flag-football-rules');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('flag-tackle','flag','nfl-flag5-guide-review-required','foundation',array['under13','13-17','18plus'],'In this NFL FLAG no-contact format, how does a defender stop a runner?','["Tackle the runner","Pull a flag legally","Push the runner down","Hold the jersey"]'::jsonb,1,'A legal flag pull replaces tackling. This does not authorize contact or holding.','https://nflflag.com/flag-football-rules');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('flag-block','flag','nfl-flag5-guide-review-required','foundation',array['under13','13-17','18plus'],'Which action is prohibited in the selected NFL FLAG no-contact guide?','["Running a route","Catching a pass","Blocking a defender","Snapping the ball"]'::jsonb,2,'The guide prohibits blocking and screening. Do not transfer a different flag league’s contact rules into this format.','https://nflflag.com/flag-football-rules');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('flag-rush','flag','nfl-flag5-guide-review-required','foundation',array['under13','13-17','18plus'],'Under this NFL FLAG guide, where must a designated rusher initially line up to rush legally?','["On the quarterback","At the sideline","One yard behind the ball","At least seven yards from the line of scrimmage"]'::jsonb,3,'This guide uses a seven-yard rush line and additional designation/timing rules. Seven yards is not a universal flag rule.','https://nflflag.com/flag-football-rules');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('flag-snap','flag','nfl-flag5-guide-review-required','foundation',array['under13','13-17','18plus'],'Who starts the play by snapping the ball?','["The center","The safety","The cornerback","The referee"]'::jsonb,0,'The center snaps the ball to begin the play. The guide also allows the center to become a receiver.','https://nflflag.com/flag-football-rules');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('flag-center','flag','nfl-flag5-guide-review-required','foundation',array['under13','13-17','18plus'],'In the selected NFL FLAG 5-on-5 guide, may the center run a route after the snap?','["Never","Yes, the center may receive a pass","Only in tackle","Only the referee can decide after a catch"]'::jsonb,1,'The center is eligible in the selected guide. Learn your own format’s eligibility rules before playing.','https://nflflag.com/flag-football-rules');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('flag-rules','flag','nfl-flag5-guide-review-required','foundation',array['under13','13-17','18plus'],'Before using a rule learned in a 5-on-5 quiz in a 7-on-7 flag game, what should you do?','["Assume all flag rules are identical","Use tackle rules","Check the actual league rulebook with your coach","Ignore rushing rules"]'::jsonb,2,'The guide explicitly explains that organizations and formats vary, especially in contact, blocking and rushing.','https://nflflag.com/flag-football-rules');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('flag-rusher-role','flag','nfl-flag5-guide-review-required','foundation',array['under13','13-17','18plus'],'What is a pass rusher trying to do in the selected flag format?','["Tackle the quarterback","Block a receiver","Hold the center","Legally pressure the passer and pull a flag or affect the pass"]'::jsonb,3,'Pressure must follow that format’s rush and no-contact rules. It is not permission to hit the passer.','https://nflflag.com/flag-football-rules');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('flag-passers','flag','nfl-flag5-guide-review-required','foundation',array['under13','13-17','18plus'],'Who is the passer on a play?','["The player throwing the pass","Always the original center","Always a defender","Any player with a flag belt"]'::jsonb,0,'The guide distinguishes the passer from a fixed position label; a legal exchange can change who throws.','https://nflflag.com/flag-football-rules');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('flag-guarding','flag','nfl-flag5-guide-review-required','foundation',array['under13','13-17','18plus'],'What does flag guarding describe?','["Reading a safety","Illegally preventing a defender from reaching your flag","Running back to the huddle","Choosing a route"]'::jsonb,1,'Do not shield or obstruct access to your flag in violation of the selected rules. Your coach should review the full rule and examples.','https://nflflag.com/flag-football-rules');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('tackle-players','tackle','tackle-fundamentals-review-required','foundation',array['under13','13-17','18plus'],'In standard 11-on-11 tackle football, how many players may each team have on the field?','["5","7","11","12"]'::jsonb,2,'Standard 11-on-11 uses eleven players per side. Do not apply that count to flag or passing-league formats.','https://operations.nfl.com/the-rules/nfl-rulebook/');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('tackle-center','tackle','tackle-fundamentals-review-required','foundation',array['under13','13-17','18plus'],'Which offensive player snaps the ball?','["The cornerback","The free safety","The referee","The center"]'::jsonb,3,'The center snaps the ball. The snap and formation must still satisfy the applicable competition rules.','https://operations.nfl.com/the-rules/nfl-rulebook/');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('tackle-los','tackle','tackle-fundamentals-review-required','foundation',array['under13','13-17','18plus'],'What does the line of scrimmage identify before a snap?','["The ball-based reference separating the teams before the play","Always the goal line","The back of the end zone","The referee’s starting position"]'::jsonb,0,'It is a ball-based pre-snap reference. The neutral zone and legal alignment requirements must be learned from the selected rulebook.','https://operations.nfl.com/the-rules/nfl-rulebook/');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('tackle-touchdown','tackle','tackle-fundamentals-review-required','foundation',array['under13','13-17','18plus'],'How many points is a touchdown worth in standard tackle football?','["3","6","7","2"]'::jsonb,1,'A touchdown is worth six points. A try is a separate play, not part of those six points.','https://operations.nfl.com/the-rules/nfl-rulebook/');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('tackle-fieldgoal','tackle','tackle-fundamentals-review-required','foundation',array['under13','13-17','18plus'],'How many points is a successful field goal worth in standard tackle football?','["1","2","3","6"]'::jsonb,2,'A successful field goal is worth three points. A try kick uses a different scoring rule.','https://operations.nfl.com/the-rules/nfl-rulebook/');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('tackle-interception','tackle','tackle-fundamentals-review-required','foundation',array['under13','13-17','18plus'],'What is an interception?','["An incomplete snap","An offensive timeout","A punt out of bounds","A defender legally catching an opponent’s pass"]'::jsonb,3,'An interception changes possession. Catch and boundary requirements come from the applicable rulebook.','https://operations.nfl.com/the-rules/nfl-rulebook/');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('tackle-incomplete','tackle','tackle-fundamentals-review-required','foundation',array['under13','13-17','18plus'],'A forward pass is ruled incomplete. What happened?','["No legal completed catch was established","The offense automatically scored","The quarterback automatically gained yards","The defense always scored"]'::jsonb,0,'An incomplete pass is not a completed catch. Exact catch and timing requirements vary across rulebooks.','https://operations.nfl.com/the-rules/nfl-rulebook/');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('tackle-safety','tackle','tackle-fundamentals-review-required','foundation',array['under13','13-17','18plus'],'In standard tackle scoring, how many points is a safety worth?','["1","2","3","6"]'::jsonb,1,'A safety is worth two points. Learn the specific situations that produce a safety with your coach.','https://operations.nfl.com/the-rules/nfl-rulebook/');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('tackle-forward','tackle','tackle-fundamentals-review-required','foundation',array['under13','13-17','18plus'],'Which description best identifies a forward pass?','["Any ball held by a quarterback","Any handoff","A pass traveling forward under the applicable rules","Any ball dropped to the ground"]'::jsonb,2,'The rulebook defines forward-pass direction and restrictions. A handoff, backward pass and fumble are different concepts.','https://operations.nfl.com/the-rules/nfl-rulebook/');
insert into public.qb_question_bank(draft_key,pathway,ruleset,difficulty,age_groups,prompt,choices,correct,explanation,source_url) values('tackle-rulebook','tackle','tackle-fundamentals-review-required','foundation',array['under13','13-17','18plus'],'When a coach says a rule differs between high school, college and the NFL, what should you use?','["The NFL rule automatically","A video-game rule","A flag rule","Your competition’s current rulebook and your coach’s explanation"]'::jsonb,3,'This quiz covers basic shared concepts. Detailed catch, timing, eligibility and penalty rules need competition-specific review.','https://operations.nfl.com/the-rules/nfl-rulebook/');
